const { panelViewSettings, viewmodel } = options.contextData;
const actionsHelper = viewmodel.ActionsHelper();
const showDocumentViewAction = actionsHelper.getAction('showdocumentview');
const filterData = viewmodel.OptionalContent().DocumentView();
const isFiltered = showDocumentViewAction.documentView;
const isEnabled = Object.keys(filterData).length || isFiltered;

return {
	disabled: !isEnabled,
	hidden: panelViewSettings.role === 'import',
	state: isEnabled && !isFiltered
};
